// Lightweight procedural sound effects — no external assets.
export class Sound {
  constructor() {
    this.ctx = null
    this.master = null
    this.enabled = true
    this.noiseBuffer = null
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {})
      return
    }
    const Ctx = window.AudioContext || window.webkitAudioContext
    if (!Ctx) return
    try {
      this.ctx = new Ctx()
      this.master = this.ctx.createGain()
      this.master.gain.value = this.enabled ? 0.55 : 0
      this.master.connect(this.ctx.destination)
      const length = Math.floor(this.ctx.sampleRate * 0.6)
      this.noiseBuffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate)
      const data = this.noiseBuffer.getChannelData(0)
      for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1
    } catch {
      this.ctx = null
    }
  }

  setEnabled(enabled) {
    this.enabled = enabled
    if (this.master) this.master.gain.value = enabled ? 0.55 : 0
    if (enabled) this.init()
  }

  tone({ freq = 440, dur = 0.15, type = 'sine', gain = 0.18, when = 0, slide = null, attack = 0.008, release = null }) {
    if (!this.ctx || !this.enabled) return
    const t = this.ctx.currentTime + when
    const osc = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(freq, t)
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slide), t + dur)
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(gain, t + attack)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur + (release || 0))
    osc.connect(g)
    g.connect(this.master)
    osc.start(t)
    osc.stop(t + dur + (release || 0) + 0.03)
  }

  noise({ dur = 0.2, gain = 0.12, when = 0, filter = 1200, q = 0.7, type = 'lowpass' }) {
    if (!this.ctx || !this.enabled || !this.noiseBuffer) return
    const t = this.ctx.currentTime + when
    const src = this.ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    const f = this.ctx.createBiquadFilter()
    f.type = type
    f.frequency.value = filter
    f.Q.value = q
    const g = this.ctx.createGain()
    g.gain.setValueAtTime(gain, t)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    src.connect(f)
    f.connect(g)
    g.connect(this.master)
    src.start(t)
    src.stop(t + dur + 0.02)
  }

  click() {
    this.tone({ freq: 620, slide: 520, dur: 0.06, type: 'triangle', gain: 0.07 })
  }

  error() {
    this.tone({ freq: 150, slide: 110, dur: 0.16, type: 'sawtooth', gain: 0.06 })
  }

  collect(full = false) {
    const base = full ? 523.25 : 440
    this.noise({ dur: 0.28, gain: 0.1, filter: 900 })
    this.tone({ freq: base, dur: 0.22, type: 'triangle', gain: 0.13 })
    this.tone({ freq: base * 1.25, dur: 0.24, type: 'sine', gain: 0.11, when: 0.06 })
    this.tone({ freq: base * 1.5, dur: 0.32, type: 'sine', gain: 0.1, when: 0.13 })
    if (full) this.tone({ freq: base * 2, dur: 0.4, type: 'triangle', gain: 0.08, when: 0.21 })
  }

  autoCollect() {
    this.tone({ freq: 880, slide: 1320, dur: 0.12, type: 'sine', gain: 0.06 })
  }

  buy() {
    this.tone({ freq: 392, dur: 0.12, type: 'triangle', gain: 0.1 })
    this.tone({ freq: 587.33, dur: 0.18, type: 'triangle', gain: 0.1, when: 0.08 })
    this.tone({ freq: 783.99, dur: 0.3, type: 'sine', gain: 0.08, when: 0.16 })
  }

  beeBuy() {
    this.tone({ freq: 300, slide: 520, dur: 0.16, type: 'sawtooth', gain: 0.045 })
    this.tone({ freq: 660, dur: 0.18, type: 'triangle', gain: 0.08, when: 0.08 })
  }

  zone() {
    this.noise({ dur: 0.7, gain: 0.09, filter: 600, q: 0.4 })
    this.tone({ freq: 261.63, dur: 0.5, type: 'sine', gain: 0.08 })
    this.tone({ freq: 392, dur: 0.6, type: 'sine', gain: 0.07, when: 0.1 })
    this.tone({ freq: 523.25, dur: 0.8, type: 'sine', gain: 0.06, when: 0.2 })
  }

  rebirth() {
    const notes = [261.63, 329.63, 392, 523.25, 659.25, 783.99]
    notes.forEach((f, i) => this.tone({ freq: f, dur: 0.7, type: 'triangle', gain: 0.09, when: i * 0.09 }))
    this.noise({ dur: 1.1, gain: 0.08, filter: 2400, q: 0.3 })
    this.tone({ freq: 1046.5, dur: 1.4, type: 'sine', gain: 0.07, when: 0.55 })
  }

  full() {
    this.tone({ freq: 783.99, dur: 0.18, type: 'triangle', gain: 0.08 })
    this.tone({ freq: 1046.5, dur: 0.3, type: 'sine', gain: 0.06, when: 0.1 })
  }
}

// Low-poly bees with flapping wings and gentle flight paths.
import * as THREE from 'three'
import { BEE_TYPES } from './data.js'
import { TAU, clamp, lerp, rand } from './world-visuals.js'

const GEO = {
  body: new THREE.SphereGeometry(0.22, 12, 9),
  stripe: new THREE.TorusGeometry(0.2, 0.032, 6, 14),
  head: new THREE.SphereGeometry(0.15, 10, 8),
  eye: new THREE.SphereGeometry(0.035, 6, 5),
  wing: new THREE.SphereGeometry(0.18, 8, 6),
  stinger: new THREE.ConeGeometry(0.045, 0.16, 6),
  antenna: new THREE.CylinderGeometry(0.008, 0.008, 0.17, 4),
  pollen: new THREE.SphereGeometry(0.045, 6, 5),
}

const materialCache = new Map()

function cachedMaterial(key, make) {
  let mat = materialCache.get(key)
  if (!mat) {
    mat = make()
    materialCache.set(key, mat)
  }
  return mat
}

function bodyMaterial(color, emissive = 0, emissiveIntensity = 0) {
  return cachedMaterial(`body-${color}-${emissive}-${emissiveIntensity}`, () => {
    const m = new THREE.MeshStandardMaterial({
      color,
      roughness: 0.42,
      metalness: 0.08,
      flatShading: true,
    })
    if (emissive) {
      m.emissive = new THREE.Color(emissive)
      m.emissiveIntensity = emissiveIntensity
    }
    return m
  })
}

const darkMat = cachedMaterial('dark', () => new THREE.MeshStandardMaterial({ color: 0x241710, roughness: 0.65 }))
const wingMat = cachedMaterial(
  'wing',
  () =>
    new THREE.MeshBasicMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 0.52,
      depthWrite: false,
      side: THREE.DoubleSide,
    }),
)
const eyeMat = cachedMaterial('eye', () => new THREE.MeshBasicMaterial({ color: 0x1a120c }))

function lerpAngle(a, b, t) {
  let d = ((b - a + Math.PI) % TAU) - Math.PI
  if (d < -Math.PI) d += TAU
  return a + d * t
}

export class Bee {
  constructor(world, type, native = false, index = 0) {
    this.world = world
    this.type = type
    this.native = native
    this.phase = Math.random() * TAU
    this.speed = rand(1.25, 2.1) * (native ? 0.92 : 1)
    this.group = new THREE.Group()
    this.group.scale.setScalar(0.001)
    this.spawnT = 0
    this.targetTimer = rand(0.2, 2)
    this.hovering = 0
    this.yaw = rand(0, TAU)
    this.pitch = 0
    this.bank = 0
    this.pos = new THREE.Vector3(rand(-2.8, -1.8), rand(1.4, 2.4), rand(0.8, 1.8))
    this.vel = new THREE.Vector3(rand(-0.3, 0.3), rand(0, 0.2), rand(0.2, 0.5))
    this.index = index
    this.target = this.pos.clone().add(new THREE.Vector3(rand(-2, 2), rand(0, 1), rand(-2, 2)))
    this.buildModel()
    this.group.position.copy(this.pos)
  }

  buildModel() {
    const t = this.type
    const scale = t.scale || 1
    const emissive =
      t.id === 'gem' ? t.body : t.id === 'gilded' ? t.body : t.native ? 0xffffff : 0
    const emissiveIntensity = t.id === 'gem' ? 0.45 : t.id === 'gilded' ? 0.22 : t.native ? 0.3 : 0
    const bodyMat = bodyMaterial(t.body, emissive, emissiveIntensity)
    const stripeMat = cachedMaterial(`stripe-${t.stripe}`, () =>
      new THREE.MeshStandardMaterial({ color: t.stripe, roughness: 0.5, flatShading: true }),
    )
    const accentMat = cachedMaterial(`accent-${t.accent}`, () =>
      new THREE.MeshStandardMaterial({
        color: t.accent,
        roughness: 0.4,
        emissive: new THREE.Color(t.accent),
        emissiveIntensity: 0.1,
      }),
    )

    const body = new THREE.Mesh(GEO.body, bodyMat)
    body.scale.set(1, 0.88, 1.48)
    this.group.add(body)

    for (const z of [0.1, -0.12]) {
      const stripe = new THREE.Mesh(GEO.stripe, stripeMat)
      stripe.position.z = z
      stripe.scale.set(1, 0.9, 1)
      this.group.add(stripe)
    }

    const head = new THREE.Mesh(GEO.head, darkMat)
    head.position.set(0, 0.01, 0.34)
    head.scale.set(1, 1, 0.9)
    this.group.add(head)

    for (const x of [-0.07, 0.07]) {
      const eye = new THREE.Mesh(GEO.eye, eyeMat)
      eye.position.set(x, 0.045, 0.465)
      this.group.add(eye)
    }

    const stinger = new THREE.Mesh(GEO.stinger, darkMat)
    stinger.position.set(0, 0, -0.36)
    stinger.rotation.x = -Math.PI / 2
    this.group.add(stinger)

    for (const x of [-0.05, 0.05]) {
      const antenna = new THREE.Mesh(GEO.antenna, darkMat)
      antenna.position.set(x, 0.15, 0.42)
      antenna.rotation.set(-0.5, 0, x > 0 ? -0.3 : 0.3)
      this.group.add(antenna)
    }

    // Tiny pollen baskets.
    for (const x of [-0.15, 0.15]) {
      const pollen = new THREE.Mesh(GEO.pollen, accentMat)
      pollen.position.set(x, -0.12, -0.02)
      this.group.add(pollen)
    }

    this.wings = []
    for (const side of [-1, 1]) {
      const pivot = new THREE.Group()
      pivot.position.set(side * 0.06, 0.15, 0.05)
      const wing = new THREE.Mesh(GEO.wing, wingMat)
      wing.scale.set(1.45, 0.05, 0.68)
      wing.position.set(side * 0.19, 0, -0.02)
      wing.rotation.z = side * 0.12
      pivot.add(wing)
      this.group.add(pivot)
      this.wings.push({ pivot, side })
    }

    this.group.scale.setScalar(scale)
    this.baseScale = scale
    this.group.traverse((obj) => {
      if (obj.isMesh) {
        obj.castShadow = false
        obj.receiveShadow = false
      }
    })
  }

  pickTarget() {
    const world = this.world
    const roll = Math.random()
    let target
    if (roll < 0.64 && world.flowerPoints.length) {
      target = world.flowerPoints[Math.floor(Math.random() * world.flowerPoints.length)].clone()
      target.x += rand(-0.25, 0.25)
      target.z += rand(-0.25, 0.25)
      target.y += rand(0.15, 0.7)
    } else if (roll < 0.84) {
      target = world.hiveEntry.clone().add(new THREE.Vector3(rand(-0.9, 0.9), rand(0.2, 1.3), rand(0.4, 1.8)))
    } else if (roll < 0.94) {
      target = world.jarTop.clone().add(new THREE.Vector3(rand(-1.2, 1.2), rand(0.4, 1.6), rand(-0.8, 1.2)))
    } else {
      target = new THREE.Vector3(rand(-3.4, 3.4), rand(2.2, 4.2), rand(-3.2, 2.6))
    }
    target.y = clamp(target.y, 0.7, 5.2)
    this.target = target
    this.targetTimer = rand(3.6, 8.5)
    this.hovering = 0
  }

  update(dt, time, bees) {
    this.spawnT = Math.min(1, this.spawnT + dt * 2.4)
    const ease = 1 - Math.pow(1 - this.spawnT, 3)
    this.group.scale.setScalar(Math.max(0.001, this.baseScale * ease))

    this.targetTimer -= dt
    const toTarget = this.target.clone().sub(this.pos)
    const dist = toTarget.length()
    if (this.targetTimer <= 0 || dist < 0.35) {
      this.hovering += dt
      if (this.hovering > 0.6) this.pickTarget()
    }

    // Smooth steering toward a wandering target.
    const desired = toTarget.lengthSq() > 0.0001 ? toTarget.normalize().multiplyScalar(this.speed) : new THREE.Vector3()
    const wobble = new THREE.Vector3(
      Math.sin(time * 1.7 + this.phase) * 0.35,
      Math.sin(time * 2.3 + this.phase * 1.7) * 0.22,
      Math.cos(time * 1.4 + this.phase) * 0.35,
    )
    desired.add(wobble)

    // Keep a polite distance from neighbours.
    for (const other of bees) {
      if (other === this) continue
      const dx = this.pos.x - other.pos.x
      const dy = this.pos.y - other.pos.y
      const dz = this.pos.z - other.pos.z
      const d2 = dx * dx + dy * dy + dz * dz
      if (d2 > 0.0001 && d2 < 0.55) {
        const inv = (0.55 - d2) * 7
        desired.x += (dx / Math.sqrt(d2)) * inv
        desired.y += (dy / Math.sqrt(d2)) * inv
        desired.z += (dz / Math.sqrt(d2)) * inv
      }
    }

    const k = 1 - Math.exp(-dt * 1.9)
    this.vel.lerp(desired, k)
    this.pos.addScaledVector(this.vel, dt)

    // Stay above the island and inside a generous boundary.
    const r = Math.hypot(this.pos.x, this.pos.z)
    if (r > 5.0) {
      this.pos.x *= 5.0 / r
      this.pos.z *= 5.0 / r
    }
    if (this.pos.y < 0.65) {
      this.pos.y = 0.65
      this.vel.y = Math.abs(this.vel.y) * 0.4
    }
    if (this.pos.y > 5.4) {
      this.pos.y = 5.4
      this.vel.y = -Math.abs(this.vel.y) * 0.3
    }

    const bob = Math.sin(time * 3.2 + this.phase) * 0.045
    this.group.position.set(this.pos.x, this.pos.y + bob, this.pos.z)

    const horiz = Math.hypot(this.vel.x, this.vel.z)
    if (horiz > 0.05) {
      this.yaw = lerpAngle(this.yaw, Math.atan2(this.vel.x, this.vel.z), Math.min(1, dt * 6))
      this.pitch = lerp(this.pitch, clamp(-Math.atan2(this.vel.y, horiz) * 0.5, -0.4, 0.4), Math.min(1, dt * 4))
      this.bank = lerp(this.bank, clamp((this.vel.x * 0.1 + Math.sin(time + this.phase) * 0.12), -0.3, 0.3), Math.min(1, dt * 4))
    }
    this.group.rotation.order = 'YXZ'
    this.group.rotation.y = this.yaw
    this.group.rotation.x = this.pitch
    this.group.rotation.z = this.bank

    const flap = Math.sin(time * 47 + this.phase) * 0.72
    for (const w of this.wings) {
      w.pivot.rotation.z = w.side * (0.1 + flap)
    }
  }

  dispose() {
    this.group.removeFromParent()
  }
}

export function buildBeeSpecs(state, zone) {
  const owned = BEE_TYPES.filter((t) => (state.bees[t.id] || 0) > 0)
  const specs = []
  const cap = 18
  for (const type of owned) {
    if (specs.length >= cap) break
    specs.push({ type })
  }
  const pool = []
  for (const type of owned) {
    const count = state.bees[type.id]
    const weight = Math.min(9, Math.max(1, Math.ceil(Math.log2(count + 1))))
    for (let i = 0; i < weight; i++) pool.push(type)
  }
  let guard = 0
  while (specs.length < cap && pool.length && guard < 80) {
    specs.push({ type: pool[(guard * 7 + 3) % pool.length] })
    guard++
  }

  const accent = new THREE.Color(zone.accent)
  const nativeType = {
    id: `native-${zone.id}`,
    name: zone.nativeBee,
    body: accent.getHex(),
    stripe: accent.clone().multiplyScalar(0.28).getHex(),
    accent: 0xfff3c4,
    scale: 0.82,
  }
  specs.push({ type: nativeType, native: true })
  specs.push({ type: nativeType, native: true })
  if (specs.length < 21) specs.push({ type: nativeType, native: true })
  return specs
}

// Procedural, thematic zone scenery for the floating honey island.
import * as THREE from 'three'
import { TAU, glowTexture, rand } from './world-visuals.js'

const G = {
  sphere: new THREE.SphereGeometry(1, 10, 8),
  ico: new THREE.IcosahedronGeometry(1, 0),
  cone: new THREE.ConeGeometry(1, 1, 7),
  cyl: new THREE.CylinderGeometry(1, 1, 1, 8),
  hex: new THREE.CylinderGeometry(1, 1, 1, 6),
  box: new THREE.BoxGeometry(1, 1, 1),
  octa: new THREE.OctahedronGeometry(1, 0),
  torus: new THREE.TorusGeometry(1, 0.14, 6, 18),
  circle: new THREE.CircleGeometry(1, 20),
}

function std(color, opts = {}) {
  return new THREE.MeshStandardMaterial({
    color,
    roughness: opts.roughness ?? 0.82,
    metalness: opts.metalness ?? 0,
    emissive: opts.emissive ?? 0x000000,
    emissiveIntensity: opts.emissiveIntensity ?? 0,
    flatShading: opts.flatShading ?? true,
    transparent: opts.transparent,
    opacity: opts.opacity ?? 1,
    side: opts.side,
  })
}

function mesh(geo, mat, x = 0, y = 0, z = 0, sx = 1, sy = 1, sz = 1) {
  const m = new THREE.Mesh(geo, mat)
  m.position.set(x, y, z)
  m.scale.set(sx, sy, sz)
  m.castShadow = true
  m.receiveShadow = true
  return m
}

const FLOWER_SPOTS = [
  [-4.0, 2.25, 1.0],
  [-2.9, 3.05, -0.55],
  [-1.15, 2.75, 0.3],
  [0.35, 3.1, 0.25],
  [2.55, 3.0, 0.85],
  [4.05, 1.65, 0.9],
  [4.15, -0.55, 0.95],
  [2.95, -2.65, 0.7],
  [0.65, -3.45, 0.6],
  [-1.6, -3.15, 0.7],
  [-4.15, -1.15, 0.8],
]

function makeFlower(kind, vis, scale = 1) {
  const group = new THREE.Group()
  const stemMat = std(vis.stem, { roughness: 0.9 })
  const leafMat = std(vis.leaf, { roughness: 0.9 })
  const petalMat = std(vis.petals[Math.floor(Math.random() * vis.petals.length)], {
    roughness: 0.65,
    emissive: kind === 'crystal' ? vis.petals[0] : 0x000000,
    emissiveIntensity: kind === 'crystal' ? 0.5 : 0,
  })
  const centerMat = std(vis.center, {
    roughness: 0.5,
    emissive: kind === 'crystal' ? vis.center : 0x000000,
    emissiveIntensity: kind === 'crystal' ? 0.65 : 0,
  })

  let topY = 0.8
  if (kind === 'cactus') {
    const stem = mesh(G.cyl, stemMat, 0, 0.25, 0, 0.09, 0.5, 0.09)
    group.add(stem)
    // Tiny arms.
    for (const side of [-1, 1]) {
      const arm = mesh(G.cyl, stemMat, side * 0.14, 0.3, 0, 0.05, 0.2, 0.05)
      group.add(arm)
    }
    topY = 0.48
  } else if (kind === 'crystal') {
    const stem = mesh(G.cyl, stemMat, 0, 0.3, 0, 0.05, 0.6, 0.05)
    group.add(stem)
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * TAU
      const shard = mesh(G.octa, petalMat, Math.cos(a) * 0.14, 0.66 + Math.sin(i) * 0.03, Math.sin(a) * 0.14, 0.09, 0.16, 0.09)
      shard.rotation.set(rand(-0.4, 0.4), a, rand(-0.4, 0.4))
      group.add(shard)
    }
    const core = mesh(G.octa, centerMat, 0, 0.78, 0, 0.1, 0.15, 0.1)
    group.add(core)
    topY = 0.82
  } else {
    const stem = mesh(G.cyl, stemMat, 0, 0.32, 0, 0.028, 0.64, 0.028)
    group.add(stem)
    const leaf = mesh(G.sphere, leafMat, 0.1, 0.3, 0.02, 0.14, 0.05, 0.08)
    leaf.rotation.z = 0.45
    group.add(leaf)
    const leaf2 = leaf.clone()
    leaf2.position.x = -0.1
    leaf2.rotation.z = -0.45
    group.add(leaf2)
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * TAU + 0.3
      const petal = mesh(G.sphere, petalMat, Math.cos(a) * 0.12, 0.7 + Math.sin(i * 1.3) * 0.02, Math.sin(a) * 0.12, 0.1, 0.045, 0.1)
      petal.rotation.y = -a
      group.add(petal)
    }
    const center = mesh(G.sphere, centerMat, 0, 0.71, 0, 0.06, 0.05, 0.06)
    group.add(center)
    topY = 0.76
  }

  group.scale.setScalar(scale)
  group.rotation.y = rand(0, TAU)
  return { group, topY: topY * scale + 0.05 * scale }
}

function makeGrass(vis, scale = 1) {
  const group = new THREE.Group()
  const mat = std(vis.leaf, { roughness: 0.92 })
  for (let i = 0; i < 4; i++) {
    const blade = mesh(G.cone, mat, rand(-0.07, 0.07), 0.14, rand(-0.07, 0.07), 0.035, 0.32, 0.035)
    blade.rotation.z = rand(-0.3, 0.3)
    group.add(blade)
  }
  group.scale.setScalar(scale)
  return group
}

function makeRock(color, scale = 1) {
  const rock = mesh(G.ico, std(color, { roughness: 0.95 }), 0, 0.18, 0, 0.42, 0.28, 0.38)
  rock.rotation.set(rand(0, 1), rand(0, TAU), rand(0, 1))
  rock.scale.multiplyScalar(scale)
  return rock
}

function makeRoundTree(vis, scale = 1) {
  const group = new THREE.Group()
  const trunkMat = std(0x8a5a32, { roughness: 0.9 })
  const leafMat = std(0x4f9b40, { roughness: 0.88 })
  const leafLight = std(0x6fbd4f, { roughness: 0.88 })
  const trunk = mesh(G.cyl, trunkMat, 0, 1.0, 0, 0.19, 2.0, 0.19)
  group.add(trunk)
  const blobs = [
    [0, 2.35, 0, 1.02],
    [0.55, 2.0, 0.2, 0.72],
    [-0.5, 2.05, -0.15, 0.68],
    [0.1, 2.8, -0.3, 0.58],
  ]
  blobs.forEach(([x, y, z, s], i) => {
    const leaf = mesh(G.ico, i % 2 ? leafLight : leafMat, x, y, z, s, s * 0.85, s)
    leaf.rotation.y = rand(0, TAU)
    group.add(leaf)
  })
  group.scale.setScalar(scale)
  return group
}

function makePine(vis, scale = 1) {
  const group = new THREE.Group()
  const trunk = mesh(G.cyl, std(0x6d4a2a), 0, 0.75, 0, 0.16, 1.5, 0.16)
  group.add(trunk)
  const green = std(0x2f6a55, { roughness: 0.85 })
  const snow = std(0xf4fdff, { roughness: 0.65 })
  const tiers = [
    [1.25, 2.4, 1.25, 1.15],
    [1.6, 1.8, 1.6, 0.95],
    [1.95, 1.15, 1.95, 0.72],
  ]
  for (const [y, h, r, s] of tiers) {
    const cone = mesh(G.cone, green, 0, y, 0, r, h, r)
    cone.position.y = y
    group.add(cone)
    const cap = mesh(G.cone, snow, 0, y + h * 0.28, 0, r * 0.72, h * 0.34, r * 0.72)
    group.add(cap)
  }
  const topSnow = mesh(G.sphere, snow, 0, 3.05, 0, 0.2, 0.16, 0.2)
  group.add(topSnow)
  group.scale.setScalar(scale)
  return group
}

function makeCactus(vis, scale = 1) {
  const group = new THREE.Group()
  const green = std(0x4f9c58, { roughness: 0.85 })
  const dark = std(0x3f7f49, { roughness: 0.9 })
  const body = mesh(G.cyl, green, 0, 0.9, 0, 0.3, 1.8, 0.3)
  group.add(body)
  const top = mesh(G.sphere, green, 0, 1.78, 0, 0.3, 0.18, 0.3)
  group.add(top)
  for (const side of [-1, 1]) {
    const arm = mesh(G.cyl, green, side * 0.42, 0.95, 0, 0.16, 0.65, 0.16)
    arm.rotation.z = side * 0.35
    group.add(arm)
    const elbow = mesh(G.sphere, green, side * 0.3, 1.25, 0, 0.17, 0.17, 0.17)
    group.add(elbow)
    const tip = mesh(G.cyl, green, side * 0.5, 1.48, 0, 0.14, 0.4, 0.14)
    group.add(tip)
    const tipTop = mesh(G.sphere, green, side * 0.5, 1.68, 0, 0.14, 0.1, 0.14)
    group.add(tipTop)
  }
  for (let i = 0; i < 4; i++) {
    const spine = mesh(G.cone, dark, rand(-0.26, 0.26), rand(0.5, 1.6), 0.28, 0.025, 0.1, 0.025)
    group.add(spine)
  }
  const bloom = makeFlower('cactus', vis, 0.8)
  bloom.group.position.set(0.04, 1.78, 0.05)
  group.add(bloom.group)
  group.scale.setScalar(scale)
  return group
}

function makePalm(vis, scale = 1) {
  const group = new THREE.Group()
  const trunkMat = std(0x9a6b3d, { roughness: 0.9 })
  const leafMat = std(0x4d9b47, { roughness: 0.85 })
  for (let i = 0; i < 5; i++) {
    const seg = mesh(G.cyl, trunkMat, Math.sin(i * 0.22) * 0.34, 0.45 + i * 0.48, 0, 0.18 - i * 0.015, 0.52, 0.18 - i * 0.015)
    seg.rotation.z = -0.12
    group.add(seg)
  }
  const crownY = 2.7
  const crownX = 0.55
  for (let i = 0; i < 7; i++) {
    const a = (i / 7) * TAU
    const leaf = mesh(G.cone, leafMat, crownX + Math.cos(a) * 0.85, crownY - 0.1, Math.sin(a) * 0.85, 0.25, 1.9, 0.12)
    leaf.rotation.z = Math.PI / 2 + 0.2
    leaf.rotation.y = -a
    leaf.position.y = crownY + Math.sin(i) * 0.12
    group.add(leaf)
  }
  const crown = mesh(G.sphere, std(0x6cb34e), crownX, crownY, 0, 0.25, 0.2, 0.25)
  group.add(crown)
  group.scale.setScalar(scale)
  return group
}

function makeCrystalCluster(vis, scale = 1) {
  const group = new THREE.Group()
  const colors = [vis.petals[0], vis.petals[1], vis.petals[2]]
  const count = 5
  for (let i = 0; i < count; i++) {
    const color = colors[i % colors.length]
    const mat = std(color, {
      roughness: 0.18,
      metalness: 0.25,
      emissive: color,
      emissiveIntensity: 0.5,
      transparent: true,
      opacity: 0.94,
    })
    const h = rand(0.6, 1.8)
    const shard = mesh(G.octa, mat, rand(-0.55, 0.55), h * 0.42, rand(-0.4, 0.4), rand(0.15, 0.32), h * 0.62, rand(0.15, 0.32))
    shard.rotation.set(rand(-0.35, 0.35), rand(0, TAU), rand(-0.35, 0.35))
    group.add(shard)
  }
  const base = makeRock(vis.rockDark, 0.8)
  group.add(base)
  group.scale.setScalar(scale)
  return group
}

function makeGlowShroom(vis, scale = 1) {
  const group = new THREE.Group()
  const stem = mesh(G.cyl, std(0x8c76b8, { emissive: 0x5b3e85, emissiveIntensity: 0.25 }), 0, 0.28, 0, 0.06, 0.56, 0.06)
  group.add(stem)
  const capColor = vis.petals[Math.floor(rand(0, vis.petals.length))]
  const cap = mesh(G.sphere, std(capColor, { emissive: capColor, emissiveIntensity: 0.55, roughness: 0.3 }), 0, 0.6, 0, 0.22, 0.12, 0.22)
  group.add(cap)
  const glow = new THREE.Sprite(
    new THREE.SpriteMaterial({ map: glowTexture(), color: capColor, transparent: true, opacity: 0.45, blending: THREE.AdditiveBlending, depthWrite: false }),
  )
  glow.position.set(0, 0.6, 0)
  glow.scale.setScalar(1.1)
  group.add(glow)
  group.scale.setScalar(scale)
  return group
}

function makeIceSpike(vis, scale = 1) {
  const group = new THREE.Group()
  const mat = std(0xd4f4ff, {
    roughness: 0.12,
    metalness: 0.15,
    emissive: 0x8fd9ff,
    emissiveIntensity: 0.18,
    transparent: true,
    opacity: 0.9,
  })
  for (let i = 0; i < 4; i++) {
    const h = rand(0.7, 1.8)
    const spike = mesh(G.cone, mat, rand(-0.35, 0.35), h * 0.5, rand(-0.3, 0.3), rand(0.14, 0.26), h, rand(0.14, 0.26))
    spike.rotation.z = rand(-0.2, 0.2)
    group.add(spike)
  }
  group.scale.setScalar(scale)
  return group
}

function makeGoldPillar(vis, scale = 1) {
  const group = new THREE.Group()
  const gold = std(0xf3c548, { roughness: 0.28, metalness: 0.72, emissive: 0x8a5b00, emissiveIntensity: 0.18 })
  const dark = std(0xb7871d, { roughness: 0.4, metalness: 0.6 })
  const h = rand(1.4, 2.8)
  const pillar = mesh(G.hex, gold, 0, h / 2, 0, 0.36, h, 0.36)
  group.add(pillar)
  const cap = mesh(G.hex, dark, 0, h + 0.12, 0, 0.44, 0.16, 0.44)
  group.add(cap)
  // Comb cells.
  for (let i = 0; i < 4; i++) {
    const cell = mesh(G.hex, dark, rand(-0.22, 0.22), rand(0.35, h - 0.15), 0.32, 0.12, 0.03, 0.12)
    group.add(cell)
  }
  group.scale.setScalar(scale)
  return group
}

function makeCoin(scale = 1) {
  const coin = new THREE.Group()
  const mat = std(0xffd35e, { roughness: 0.25, metalness: 0.8, emissive: 0x8a5a00, emissiveIntensity: 0.2 })
  const disc = mesh(G.cyl, mat, 0, 0.06, 0, 0.3, 0.08, 0.3)
  disc.rotation.x = Math.PI / 2
  disc.rotation.z = rand(0, TAU)
  coin.add(disc)
  coin.scale.setScalar(scale)
  return coin
}

function makeButterfly(color) {
  const group = new THREE.Group()
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.85, side: THREE.DoubleSide })
  const wingGeo = new THREE.CircleGeometry(0.12, 6)
  for (const side of [-1, 1]) {
    const wing = new THREE.Mesh(wingGeo, mat)
    wing.position.x = side * 0.11
    wing.scale.set(1, 1.5, 1)
    group.add(wing)
  }
  return group
}

function makeFence(vis) {
  const group = new THREE.Group()
  const wood = std(0x9a6a38, { roughness: 0.9 })
  for (let i = 0; i < 5; i++) {
    const x = -4.2 + i * 0.62
    const z = -2.05 - i * 0.36
    const post = mesh(G.box, wood, x, 0.5, z, 0.13, 1.0, 0.13)
    group.add(post)
    const tip = mesh(G.cone, wood, x, 1.04, z, 0.1, 0.16, 0.1)
    group.add(tip)
  }
  for (let r = 0; r < 2; r++) {
    const rail = mesh(G.box, wood, -3.0, 0.38 + r * 0.31, -2.73, 2.75, 0.07, 0.08)
    rail.rotation.y = -0.53
    group.add(rail)
  }
  return group
}

function makePond(vis) {
  const group = new THREE.Group()
  const ice = mesh(G.circle, std(0xbfefff, { roughness: 0.1, metalness: 0.3, transparent: true, opacity: 0.82 }), 0, 0.025, 0, 1.45, 1.45, 1.45)
  ice.rotation.x = -Math.PI / 2
  group.add(ice)
  const rimMat = std(0xe4fbff, { roughness: 0.4 })
  for (let i = 0; i < 9; i++) {
    const a = (i / 9) * TAU
    const snow = mesh(G.ico, rimMat, Math.cos(a) * 1.42, 0.09, Math.sin(a) * 1.1, 0.22, 0.13, 0.2)
    group.add(snow)
  }
  group.position.set(-0.45, 0, -3.1)
  return group
}

function makeAmbientParticles(vis) {
  const cfg = vis.ambientMotes
  const count = cfg.count
  const positions = new Float32Array(count * 3)
  const speeds = new Float32Array(count)
  for (let i = 0; i < count; i++) {
    const a = rand(0, TAU)
    const r = Math.sqrt(Math.random()) * 6.2
    positions[i * 3] = Math.cos(a) * r
    positions[i * 3 + 1] = rand(0.5, cfg.mode === 'snow' ? 7 : 5.5)
    positions[i * 3 + 2] = Math.sin(a) * r
    speeds[i] = rand(0.55, 1.45)
  }
  const geo = new THREE.BufferGeometry()
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3))
  const isSnow = cfg.mode === 'snow'
  const mat = new THREE.PointsMaterial({
    color: cfg.color,
    size: isSnow ? 0.1 : 0.075,
    transparent: true,
    opacity: isSnow ? 0.9 : 0.75,
    depthWrite: false,
    blending: isSnow ? THREE.NormalBlending : THREE.AdditiveBlending,
    sizeAttenuation: true,
  })
  const points = new THREE.Points(geo, mat)
  points.frustumCulled = false
  points.userData = { cfg, speeds }
  return points
}

export function createZoneEnvironment(zone, vis) {
  const group = new THREE.Group()
  const flowerPoints = []
  const bobbers = []

  const addFlower = (x, z, kind, scale = rand(0.9, 1.25)) => {
    const flower = makeFlower(kind, vis, scale)
    flower.group.position.set(x, 0, z)
    group.add(flower.group)
    flowerPoints.push(new THREE.Vector3(x, flower.topY + 0.2, z))
  }

  const addGrass = (count, color) => {
    for (let i = 0; i < count; i++) {
      const a = rand(0, TAU)
      const r = rand(2.0, 5.0)
      const x = Math.cos(a) * r
      const z = Math.sin(a) * r
      if (Math.hypot(x - 1.9, z - 0.7) < 1.7) continue
      if (Math.hypot(x + 2.5, z) < 1.4) continue
      const g = makeGrass(vis, rand(0.7, 1.3))
      g.position.set(x, 0, z)
      group.add(g)
    }
  }

  const addRock = (x, z, scale = 1, matColor = vis.rock) => {
    const rock = makeRock(matColor, scale)
    rock.position.x = x
    rock.position.z = z
    group.add(rock)
  }

  if (zone.id === 'meadow') {
    addFlower(FLOWER_SPOTS[0][0], -FLOWER_SPOTS[0][1], 'flower')
    addFlower(FLOWER_SPOTS[1][0], -FLOWER_SPOTS[1][1], 'flower')
    addFlower(FLOWER_SPOTS[2][0], -FLOWER_SPOTS[2][1], 'flower')
    addFlower(FLOWER_SPOTS[3][0], -FLOWER_SPOTS[3][1], 'flower')
    addFlower(FLOWER_SPOTS[4][0], -FLOWER_SPOTS[4][1], 'flower')
    addFlower(FLOWER_SPOTS[5][0], -FLOWER_SPOTS[5][1], 'flower')
    addFlower(FLOWER_SPOTS[6][0], -FLOWER_SPOTS[6][1], 'flower')
    addFlower(FLOWER_SPOTS[7][0], -FLOWER_SPOTS[7][1], 'flower')
    addFlower(FLOWER_SPOTS[8][0], -FLOWER_SPOTS[8][1], 'flower')
    addFlower(FLOWER_SPOTS[9][0], -FLOWER_SPOTS[9][1], 'flower')
    addFlower(FLOWER_SPOTS[10][0], -FLOWER_SPOTS[10][1], 'flower')

    const tree1 = makeRoundTree(vis, 1.15)
    tree1.position.set(-4.25, 0, -1.9)
    group.add(tree1)
    const tree2 = makeRoundTree(vis, 1.0)
    tree2.position.set(4.35, 0, -2.35)
    group.add(tree2)
    const tree3 = makeRoundTree(vis, 0.72)
    tree3.position.set(-3.2, 0, -3.4)
    group.add(tree3)

    const bushMat = std(0x5aa846, { roughness: 0.9 })
    for (const [x, z, s] of [
      [3.85, 1.7, 0.6],
      [-3.6, 1.2, 0.45],
      [-0.5, -3.9, 0.5],
    ]) {
      const bush = mesh(G.ico, bushMat, x, s * 0.35, z, s, s * 0.7, s)
      group.add(bush)
    }
    addFence(vis)
    for (const [x, z, s] of [
      [-4.7, 0.5, 0.9],
      [3.9, -0.7, 0.6],
      [-2.2, 3.8, 0.55],
      [4.8, 2.3, 0.7],
    ])
      addRock(x, z, s)
    addGrass(18)
    for (const [x, z, c] of [
      [-4.1, 2.15, 0xffd35e],
      [0.5, 2.95, 0xff8fa7],
      [3.95, 1.55, 0xb98cff],
    ]) {
      const butterfly = makeButterfly(c)
      butterfly.position.set(x, 1.1, z)
      group.add(butterfly)
      bobbers.push({ mesh: butterfly, baseY: 1.1, amp: 0.2, speed: 1.4, phase: rand(0, TAU), spin: 0.8 })
    }
    // Mushrooms.
    for (const [x, z] of [
      [-3.3, 1.9],
      [2.2, -3.3],
      [-0.2, -2.3],
    ]) {
      const shroom = makeGlowShroom({ ...vis, petals: [0xffbc5c, 0xffe08a, 0xff9e6b] }, rand(0.8, 1.2))
      shroom.position.set(x, 0, z)
      group.add(shroom)
    }
  }

  if (zone.id === 'desert') {
    for (let i = 0; i < 9; i++) {
      const s = FLOWER_SPOTS[i]
      addFlower(s[0], -s[1], 'cactus', rand(0.8, 1.05))
    }
    const palm = makePalm(vis, 1.25)
    palm.position.set(4.35, 0, -1.4)
    group.add(palm)
    const palm2 = makePalm(vis, 0.8)
    palm2.position.set(-4.35, 0, -2.6)
    group.add(palm2)
    for (const [x, z, s] of [
      [-4.0, 0.45, 1.15],
      [-3.5, 2.75, 0.85],
      [3.1, -3.25, 0.9],
      [1.2, -3.9, 0.65],
    ]) {
      const cactus = makeCactus(vis, s)
      cactus.position.set(x, 0, z)
      group.add(cactus)
    }
    for (const [x, z, s] of [
      [-4.8, 0.8, 0.9],
      [2.9, 2.5, 0.7],
      [4.4, 1.9, 0.6],
      [-1.5, -4.0, 0.8],
      [0.4, -2.8, 0.5],
    ])
      addRock(x, z, s, vis.rock)
    // Dry shrubs.
    const dry = std(0xb28a54, { roughness: 0.95 })
    for (const [x, z] of [
      [-2.5, 2.7],
      [2.1, 2.3],
      [-1.2, -2.6],
    ]) {
      for (let i = 0; i < 5; i++) {
        const blade = mesh(G.cone, dry, x + rand(-0.2, 0.2), 0.22, z + rand(-0.2, 0.2), 0.035, 0.5, 0.035)
        blade.rotation.z = rand(-0.6, 0.6)
        group.add(blade)
      }
    }
    addGrass(8)
    // Bleached bones.
    for (const [x, z] of [
      [0.8, -2.2],
      [-2.8, 1.2],
    ]) {
      const boneMat = std(0xf2e3c4, { roughness: 0.9 })
      const bone = mesh(G.cyl, boneMat, x, 0.07, z, 0.04, 0.5, 0.04)
      bone.rotation.z = Math.PI / 2
      bone.rotation.y = rand(0, TAU)
      group.add(bone)
    }
    // Heat shimmer glints.
    for (let i = 0; i < 2; i++) {
      const glow = new THREE.Sprite(
        new THREE.SpriteMaterial({ map: glowTexture(), color: 0xffe4ad, transparent: true, opacity: 0.25, blending: THREE.AdditiveBlending, depthWrite: false }),
      )
      glow.position.set(rand(-4, 4), rand(2, 3.5), rand(-3, 3))
      glow.scale.setScalar(1.5)
      group.add(glow)
      bobbers.push({ mesh: glow, baseY: glow.position.y, amp: 0.3, speed: 0.6, phase: rand(0, TAU), spin: 0 })
    }
  }

  if (zone.id === 'crystal') {
    for (let i = 0; i < 9; i++) {
      const s = FLOWER_SPOTS[i]
      addFlower(s[0], -s[1], 'crystal', rand(0.8, 1.15))
    }
    for (const [x, z, s] of [
      [-4.05, -2.2, 1.35],
      [4.1, -1.9, 1.15],
      [3.9, 2.35, 0.85],
      [-3.9, 2.0, 0.75],
      [0.3, -4.1, 0.9],
      [-1.0, -3.7, 0.6],
    ]) {
      const cluster = makeCrystalCluster(vis, s)
      cluster.position.set(x, 0, z)
      group.add(cluster)
    }
    for (const [x, z] of [
      [-3.3, 1.6],
      [2.1, 2.7],
      [-0.4, -2.8],
      [2.9, -0.2],
    ]) {
      const shroom = makeGlowShroom(vis, rand(0.9, 1.4))
      shroom.position.set(x, 0, z)
      group.add(shroom)
    }
    for (const [x, y, z, s] of [
      [-4.0, 3.5, -2.0, 0.5],
      [3.8, 4.1, -2.6, 0.6],
      [0.6, 3.1, -3.8, 0.4],
      [-2.2, 2.8, 2.8, 0.38],
    ]) {
      const shard = new THREE.Mesh(G.octa, std(vis.petals[Math.floor(rand(0, 4))], { roughness: 0.2, metalness: 0.3, emissive: vis.petals[0], emissiveIntensity: 0.55 }))
      shard.position.set(x, y, z)
      shard.scale.set(s, s * 1.8, s)
      shard.rotation.set(rand(0, 1), rand(0, TAU), rand(0, 1))
      group.add(shard)
      bobbers.push({ mesh: shard, baseY: y, amp: 0.35, speed: 0.8, phase: rand(0, TAU), spin: 0.35 })
    }
    addRock(-4.8, 0.5, 0.9, vis.rockDark)
    addRock(4.7, 1.2, 0.7, vis.rock)
    addRock(0.1, 2.9, 0.55, vis.rockDark)
    // Sparkling floor veins.
    const veinMat = new THREE.MeshBasicMaterial({ color: 0x9b6bff, transparent: true, opacity: 0.35, blending: THREE.AdditiveBlending, depthWrite: false })
    for (let i = 0; i < 7; i++) {
      const vein = new THREE.Mesh(G.box, veinMat)
      vein.position.set(rand(-4.5, 4.5), 0.02, rand(-4, 3.5))
      vein.scale.set(rand(0.04, 0.08), 0.01, rand(0.4, 1.3))
      vein.rotation.y = rand(0, TAU)
      group.add(vein)
    }
  }

  if (zone.id === 'frost') {
    for (let i = 0; i < 9; i++) {
      const s = FLOWER_SPOTS[i]
      addFlower(s[0], -s[1], 'flower', rand(0.85, 1.15))
    }
    for (const [x, z, s] of [
      [-4.2, -2.3, 1.15],
      [4.25, -2.6, 1.0],
      [3.6, 2.75, 0.8],
      [-3.5, 2.6, 0.7],
    ]) {
      const pine = makePine(vis, s)
      pine.position.set(x, 0, z)
      group.add(pine)
    }
    for (const [x, z, s] of [
      [-3.9, -0.5, 1.1],
      [4.15, 0.5, 0.8],
      [-1.2, -3.8, 0.7],
      [2.6, -3.6, 0.55],
    ]) {
      const spike = makeIceSpike(vis, s)
      spike.position.set(x, 0, z)
      group.add(spike)
    }
    group.add(makePond(vis))
    for (const [x, z, s] of [
      [-4.65, 1.4, 0.6],
      [2.9, 2.2, 0.5],
      [1.3, -2.6, 0.4],
    ])
      addRock(x, z, s, vis.rock)
    // Snow mounds.
    const snowMat = std(0xffffff, { roughness: 0.75 })
    for (let i = 0; i < 9; i++) {
      const a = rand(0, TAU)
      const r = rand(1.5, 4.7)
      const mound = mesh(G.sphere, snowMat, Math.cos(a) * r, 0.02, Math.sin(a) * r, rand(0.3, 0.6), rand(0.08, 0.16), rand(0.3, 0.6))
      group.add(mound)
    }
    // Aurora ribbons.
    const auroraGeo = new THREE.PlaneGeometry(18, 3.2, 24, 1)
    const auroraMat = new THREE.MeshBasicMaterial({
      color: 0x9cffe1,
      transparent: true,
      opacity: 0.14,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    })
    for (let i = 0; i < 2; i++) {
      const ribbon = new THREE.Mesh(auroraGeo, auroraMat.clone())
      ribbon.material.color.setHex(i ? 0xb59cff : 0x9cffe1)
      ribbon.position.set(rand(-4, 4), 8.5 + i * 1.6, -19 - i * 3)
      ribbon.rotation.x = -0.2
      ribbon.rotation.z = rand(-0.15, 0.15)
      group.add(ribbon)
      bobbers.push({ mesh: ribbon, baseY: ribbon.position.y, amp: 0.35, speed: 0.4, phase: rand(0, TAU), spin: 0 })
    }
  }

  if (zone.id === 'gold') {
    for (let i = 0; i < 9; i++) {
      const s = FLOWER_SPOTS[i]
      addFlower(s[0], -s[1], 'flower', rand(0.9, 1.2))
    }
    for (const [x, z, s] of [
      [-4.25, -2.2, 1.1],
      [4.4, -2.45, 1.25],
      [3.9, 2.25, 0.85],
      [-3.85, 2.4, 0.9],
      [1.4, -4.0, 0.7],
    ]) {
      const pillar = makeGoldPillar(vis, s)
      pillar.position.set(x, 0, z)
      group.add(pillar)
    }
    for (const [x, z, s] of [
      [-3.2, 1.55, 1.2],
      [2.4, 2.65, 1.0],
      [3.1, -0.5, 0.8],
      [-1.1, -2.6, 0.9],
      [0.4, -3.4, 0.7],
    ]) {
      const coin = makeCoin(s)
      coin.position.set(x, 0, z)
      group.add(coin)
    }
    // Golden orbs.
    for (const [x, y, z, s] of [
      [-3.7, 3.1, -1.7, 0.3],
      [3.5, 4.0, -2.1, 0.35],
      [0.3, 2.6, -3.6, 0.24],
      [-1.8, 2.5, 2.9, 0.2],
    ]) {
      const orb = new THREE.Mesh(G.sphere, std(0xffd75e, { emissive: 0xffb300, emissiveIntensity: 0.45, roughness: 0.15, metalness: 0.6 }))
      orb.position.set(x, y, z)
      orb.scale.setScalar(s)
      group.add(orb)
      const glow = new THREE.Sprite(
        new THREE.SpriteMaterial({ map: glowTexture(), color: 0xffe28a, transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending, depthWrite: false }),
      )
      glow.position.copy(orb.position)
      glow.scale.setScalar(s * 4)
      group.add(glow)
      bobbers.push({ mesh: orb, baseY: y, amp: 0.4, speed: 0.75, phase: rand(0, TAU), spin: 0.3 })
      bobbers.push({ mesh: glow, baseY: y, amp: 0.4, speed: 0.75, phase: rand(0, TAU), spin: 0 })
    }
    // Honeycomb wall in the back.
    const combMat = std(0xd79d22, { roughness: 0.35, metalness: 0.55, emissive: 0x7a4e00, emissiveIntensity: 0.18 })
    for (let r = 0; r < 2; r++) {
      for (let i = 0; i < 6; i++) {
        const cell = new THREE.Mesh(G.hex, combMat)
        cell.position.set(-1.8 + i * 0.72 + (r % 2) * 0.36, 1.5 + r * 0.62, -4.65)
        cell.rotation.x = Math.PI / 2
        cell.scale.set(0.34, 0.09, 0.34)
        group.add(cell)
      }
    }
    addRock(-4.7, 1.1, 0.6, vis.rock)
    addRock(3.2, 1.3, 0.45, vis.rockDark)
  }

  const particles = makeAmbientParticles(vis)
  group.add(particles)

  group.traverse((obj) => {
    if (obj.isMesh) {
      obj.castShadow = obj.castShadow && !obj.material.transparent
      obj.receiveShadow = true
    }
  })

  return {
    group,
    flowerPoints,
    bobbers,
    particles,
    updateParticles: (dt, time) => updateAmbientParticles(particles, dt, time),
    updateBobbers: (dt, time) => updateBobberList(bobbers, time),
  }
}

export function updateAmbientParticles(particles, dt, time) {
  const pos = particles.geometry.getAttribute('position')
  const arr = pos.array
  const { cfg, speeds } = particles.userData
  const mode = cfg.mode
  for (let i = 0; i < arr.length / 3; i++) {
    const speed = speeds[i] * cfg.speed
    if (mode === 'snow') {
      arr[i * 3 + 1] -= speed * dt
      arr[i * 3] += Math.sin(time * 1.2 + i) * dt * 0.18
      if (arr[i * 3 + 1] < 0.2) {
        arr[i * 3 + 1] = rand(5.5, 7.5)
        arr[i * 3] = rand(-6, 6)
        arr[i * 3 + 2] = rand(-6, 6)
      }
    } else if (mode === 'drift') {
      arr[i * 3] += speed * dt * 0.5
      arr[i * 3 + 1] += Math.sin(time * 0.8 + i) * dt * 0.06
      if (arr[i * 3] > 6.2) arr[i * 3] = -6.2
    } else {
      arr[i * 3 + 1] += speed * dt
      arr[i * 3] += Math.sin(time * 1.1 + i * 0.7) * dt * 0.12
      if (arr[i * 3 + 1] > 6.4) {
        arr[i * 3 + 1] = 0.4
        arr[i * 3] = rand(-6, 6)
        arr[i * 3 + 2] = rand(-6, 6)
      }
    }
  }
  pos.needsUpdate = true
  if (mode !== 'snow') {
    particles.material.opacity = 0.62 + Math.sin(time * 1.7) * 0.12
  }
}

export function updateBobberList(bobbers, time) {
  for (const b of bobbers) {
    b.mesh.position.y = b.baseY + Math.sin(time * b.speed + b.phase) * b.amp
    if (b.spin) b.mesh.rotation.y += b.spin * 0.008
  }
}

// The giant honey jar: glass, rising honey, ripples, label, themed charms.
import * as THREE from 'three'
import { glowTexture, makeFullTexture, makeJarLabelTexture, roundRect, TAU, lerp } from './world-visuals.js'

export const JAR_POS = new THREE.Vector3(1.9, 0.3, 0.72)
export const JAR_BASE_Y = 0.1
export const JAR_MAX_HONEY = 1.34
export const JAR_MOUTH_LOCAL = 2.13

const JAR_SCALES = {
  meadow: [1, 1, 1],
  desert: [1.08, 0.97, 1.08],
  crystal: [0.95, 1.08, 0.95],
  frost: [1.06, 1.01, 1.06],
  gold: [1.12, 0.99, 1.12],
}

const G = {
  torus: new THREE.TorusGeometry(1, 0.028, 6, 40),
  surface: new THREE.CircleGeometry(1, 40),
  bubble: new THREE.SphereGeometry(0.045, 6, 5),
  cone: new THREE.ConeGeometry(1, 1, 6),
  sphere: new THREE.SphereGeometry(1, 10, 8),
  octa: new THREE.OctahedronGeometry(1, 0),
  cyl: new THREE.CylinderGeometry(1, 1, 1, 16),
  box: new THREE.BoxGeometry(1, 1, 1),
}

function lathePoints() {
  return [
    [0.9, 0],
    [1.01, 0.03],
    [1.07, 0.16],
    [1.07, 1.42],
    [1.0, 1.56],
    [0.8, 1.8],
    [0.65, 1.91],
    [0.65, 2.01],
    [0.73, 2.06],
    [0.75, 2.12],
    [0.7, 2.14],
  ].map(([x, y]) => new THREE.Vector2(x, y))
}

export class JarVisual {
  constructor() {
    this.group = new THREE.Group()
    this.group.position.copy(JAR_POS)
    this.fill = 0
    this.fullAmount = 0
    this.full = false
    this.targetFill = 0
    this.bounce = 0
    this.zone = null
    this.buildGlass()
    this.buildHoney()
    this.buildLabel()
    this.buildCharm()
    this.buildLid()
    this.buildFullSprite()
  }

  buildGlass() {
    const geo = new THREE.LatheGeometry(lathePoints(), 44)
    this.glassMat = new THREE.MeshPhysicalMaterial({
      color: 0xd9f4ff,
      roughness: 0.06,
      metalness: 0.0,
      transparent: true,
      opacity: 0.22,
      clearcoat: 1,
      clearcoatRoughness: 0.06,
      side: THREE.DoubleSide,
      depthWrite: false,
      envMapIntensity: 1.4,
    })
    this.glass = new THREE.Mesh(geo, this.glassMat)
    this.glass.renderOrder = 2
    this.group.add(this.glass)

    // Inner glass rim highlight.
    this.rimMat = new THREE.MeshStandardMaterial({ color: 0xf0b43c, roughness: 0.28, metalness: 0.75 })
    this.rim = new THREE.Mesh(new THREE.TorusGeometry(0.73, 0.06, 8, 40), this.rimMat)
    this.rim.position.y = 2.13
    this.rim.rotation.x = Math.PI / 2
    this.rim.castShadow = true
    this.group.add(this.rim)

    // A subtle vertical glint on the glass.
    const glintMat = new THREE.MeshBasicMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 0.2,
      depthWrite: false,
      side: THREE.DoubleSide,
    })
    this.glint = new THREE.Mesh(new THREE.PlaneGeometry(0.16, 1.2), glintMat)
    this.glint.position.set(-0.62, 0.92, 0.82)
    this.glint.rotation.y = 0.55
    this.group.add(this.glint)
  }

  buildHoney() {
    this.honeyMat = new THREE.MeshStandardMaterial({
      color: 0xf2a51b,
      roughness: 0.18,
      metalness: 0.12,
      emissive: 0xf2a51b,
      emissiveIntensity: 0.16,
      transparent: true,
      opacity: 0.96,
    })
    this.honey = new THREE.Mesh(new THREE.CylinderGeometry(0.955, 0.955, 1, 32, 1), this.honeyMat)
    this.honey.castShadow = false
    this.group.add(this.honey)

    this.surfaceMat = new THREE.MeshStandardMaterial({
      color: 0xffc94a,
      roughness: 0.08,
      metalness: 0.2,
      emissive: 0xffb300,
      emissiveIntensity: 0.5,
    })
    this.surface = new THREE.Mesh(G.surface, this.surfaceMat)
    this.surface.rotation.x = -Math.PI / 2
    this.surface.scale.setScalar(0.95)
    this.group.add(this.surface)

    this.rippleMat = new THREE.MeshBasicMaterial({
      color: 0xffe08a,
      transparent: true,
      opacity: 0.6,
      depthWrite: false,
      side: THREE.DoubleSide,
    })
    this.ripples = []
    for (let i = 0; i < 3; i++) {
      const ring = new THREE.Mesh(G.torus, this.rippleMat.clone())
      ring.rotation.x = Math.PI / 2
      ring.scale.setScalar(0.35 + i * 0.18)
      this.group.add(ring)
      this.ripples.push({ mesh: ring, phase: i * 0.33 })
    }

    this.bubbles = []
    this.bubbleMat = new THREE.MeshStandardMaterial({
      color: 0xffd970,
      roughness: 0.15,
      metalness: 0.1,
      transparent: true,
      opacity: 0.7,
      emissive: 0xffc21a,
      emissiveIntensity: 0.25,
    })
    for (let i = 0; i < 7; i++) {
      const bubble = new THREE.Mesh(G.bubble, this.bubbleMat)
      bubble.userData = {
        x: (Math.random() - 0.5) * 1.5,
        z: (Math.random() - 0.5) * 1.5,
        speed: 0.3 + Math.random() * 0.4,
        phase: Math.random(),
        scale: 0.5 + Math.random() * 1.1,
      }
      this.group.add(bubble)
      this.bubbles.push(bubble)
    }

    // Golden glow inside the jar.
    this.innerGlow = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: glowTexture(),
        color: 0xffc433,
        transparent: true,
        opacity: 0.18,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      }),
    )
    this.innerGlow.position.y = 0.9
    this.innerGlow.scale.set(3.4, 3.4, 1)
    this.group.add(this.innerGlow)
  }

  buildLabel() {
    this.labelMat = new THREE.MeshStandardMaterial({
      map: null,
      roughness: 0.62,
      metalness: 0,
      transparent: true,
      side: THREE.DoubleSide,
    })
    this.label = new THREE.Mesh(new THREE.PlaneGeometry(1.55, 0.78), this.labelMat)
    this.label.position.set(0, 0.94, 1.045)
    this.label.rotation.x = -0.015
    this.group.add(this.label)
  }

  buildCharm() {
    this.charmGroup = new THREE.Group()
    this.group.add(this.charmGroup)
    this.charmBob = 0
  }

  buildLid() {
    this.lidGroup = new THREE.Group()
    this.lidMat = new THREE.MeshStandardMaterial({ color: 0x8a5a32, roughness: 0.72 })
    const lid = new THREE.Mesh(new THREE.CylinderGeometry(0.78, 0.8, 0.13, 28), this.lidMat)
    lid.position.set(0, 0.07, 0)
    lid.castShadow = true
    this.lidGroup.add(lid)
    const rim = new THREE.Mesh(new THREE.TorusGeometry(0.79, 0.035, 6, 28), this.rimMat)
    rim.rotation.x = Math.PI / 2
    rim.position.y = 0.13
    this.lidGroup.add(rim)
    const knob = new THREE.Mesh(new THREE.SphereGeometry(0.12, 10, 8), this.lidMat)
    knob.position.y = 0.18
    this.lidGroup.add(knob)
    this.lidGroup.position.set(1.72, 0.02, 0.55)
    this.lidGroup.rotation.y = 0.4
    this.group.add(this.lidGroup)
  }

  buildFullSprite() {
    this.fullMat = new THREE.SpriteMaterial({
      map: makeFullTexture(),
      transparent: true,
      depthTest: false,
      depthWrite: false,
      opacity: 0,
    })
    this.fullSprite = new THREE.Sprite(this.fullMat)
    this.fullSprite.position.set(0, 2.95, 0.2)
    this.fullSprite.scale.set(2.6, 0.91, 1)
    this.fullSprite.renderOrder = 20
    this.fullSprite.visible = false
    this.group.add(this.fullSprite)
  }

  setZone(zone, visual) {
    this.zone = zone
    const oldMap = this.labelMat.map
    if (oldMap) oldMap.dispose()
    this.labelMat.map = makeJarLabelTexture(zone)
    this.labelMat.needsUpdate = true

    this.glassMat.color.setHex(visual.glass)
    this.honeyMat.color.setHex(visual.honey)
    this.honeyMat.emissive.setHex(visual.honey)
    this.surfaceMat.color.setHex(visual.honeyLight)
    this.surfaceMat.emissive.setHex(visual.honey)
    this.rippleMat.color.setHex(visual.honeyLight)
    this.rimMat.color.setHex(visual.rimColor)
    this.lidMat.color.setHex(visual.lid)
    this.innerGlow.material.color.setHex(visual.honeyLight)
    this.bubbleMat.color.setHex(visual.honeyLight)
    this.bubbleMat.emissive.setHex(visual.honey)

    const s = JAR_SCALES[zone.id] || JAR_SCALES.meadow
    this.group.scale.set(s[0], s[1], s[2])
    this.buildCharmFor(zone, visual)
    // Label colour tint stays cream; update the name only.
    this.lidGroup.visible = true
  }

  buildCharmFor(zone, visual) {
    // Clear old charm.
    while (this.charmGroup.children.length) {
      const c = this.charmGroup.children.pop()
      c.traverse?.((o) => {
        if (o.isMesh) {
          o.geometry?.dispose?.()
          o.material?.dispose?.()
        }
      })
    }
    const g = this.charmGroup
    if (zone.id === 'meadow') {
      const center = new THREE.Mesh(
        new THREE.SphereGeometry(0.1, 10, 8),
        new THREE.MeshStandardMaterial({ color: 0xffc53d, roughness: 0.5, emissive: 0xffb300, emissiveIntensity: 0.2 }),
      )
      center.position.set(0.42, 2.2, 0.6)
      g.add(center)
      for (let i = 0; i < 6; i++) {
        const a = (i / 6) * TAU
        const petal = new THREE.Mesh(
          new THREE.SphereGeometry(0.09, 8, 6),
          new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.55 }),
        )
        petal.position.set(0.42 + Math.cos(a) * 0.14, 2.2, 0.6 + Math.sin(a) * 0.14)
        petal.scale.set(1, 0.4, 1)
        g.add(petal)
      }
    } else if (zone.id === 'desert') {
      const mat = new THREE.MeshStandardMaterial({ color: 0x5fa851, roughness: 0.7 })
      const body = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.07, 0.32, 7), mat)
      body.position.set(0.42, 2.17, 0.58)
      g.add(body)
      const arm = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.04, 0.17, 6), mat)
      arm.position.set(0.5, 2.24, 0.58)
      arm.rotation.z = -0.7
      g.add(arm)
      const bloom = new THREE.Mesh(
        new THREE.SphereGeometry(0.075, 8, 6),
        new THREE.MeshStandardMaterial({ color: 0xff8b5e, emissive: 0xff6a2e, emissiveIntensity: 0.35, roughness: 0.5 }),
      )
      bloom.position.set(0.42, 2.36, 0.58)
      g.add(bloom)
    } else if (zone.id === 'crystal') {
      const gem = new THREE.Mesh(
        new THREE.OctahedronGeometry(0.2, 0),
        new THREE.MeshStandardMaterial({
          color: 0xb98cff,
          roughness: 0.12,
          metalness: 0.35,
          emissive: 0xb98cff,
          emissiveIntensity: 0.8,
          transparent: true,
          opacity: 0.92,
        }),
      )
      gem.position.set(0.42, 2.48, 0.48)
      g.add(gem)
      this.charmBob = 2.48
      const glow = new THREE.Sprite(
        new THREE.SpriteMaterial({
          map: glowTexture(),
          color: 0xd8b3ff,
          transparent: true,
          opacity: 0.7,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
        }),
      )
      glow.position.copy(gem.position)
      glow.scale.setScalar(1.1)
      g.add(glow)
      this.charmGlow = glow
    } else if (zone.id === 'frost') {
      const mat = new THREE.MeshStandardMaterial({
        color: 0xd4f7ff,
        roughness: 0.1,
        metalness: 0.15,
        transparent: true,
        opacity: 0.85,
        emissive: 0x8fd9ff,
        emissiveIntensity: 0.25,
      })
      for (let i = 0; i < 3; i++) {
        const icicle = new THREE.Mesh(new THREE.ConeGeometry(0.045, 0.3 + i * 0.06, 6), mat)
        icicle.position.set(0.3 + i * 0.14, 2.0 - i * 0.03, 0.58)
        icicle.rotation.x = Math.PI
        g.add(icicle)
      }
    } else if (zone.id === 'gold') {
      const mat = new THREE.MeshStandardMaterial({
        color: 0xffdf6e,
        roughness: 0.2,
        metalness: 0.85,
        emissive: 0xb87a00,
        emissiveIntensity: 0.25,
      })
      const crown = new THREE.Group()
      const band = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.22, 0.12, 12, 1, true), mat)
      band.position.y = 0.04
      crown.add(band)
      for (let i = 0; i < 6; i++) {
        const a = (i / 6) * TAU
        const spike = new THREE.Mesh(new THREE.ConeGeometry(0.045, 0.16, 4), mat)
        spike.position.set(Math.cos(a) * 0.19, 0.16, Math.sin(a) * 0.19)
        crown.add(spike)
      }
      crown.position.set(0.36, 2.2, 0.5)
      g.add(crown)
    }
  }

  mouthWorldY() {
    return this.group.position.y + JAR_MOUTH_LOCAL * this.group.scale.y
  }

  surfaceWorldY() {
    return this.group.position.y + (JAR_BASE_Y + this.fill * JAR_MAX_HONEY) * this.group.scale.y
  }

  surfaceRadius() {
    return 0.95 * Math.max(this.group.scale.x, this.group.scale.z)
  }

  collectBounce() {
    this.bounce = 1
  }

  update(dt, time, targetFill, rate) {
    this.targetFill = clamp01(targetFill)
    const speed = this.targetFill < this.fill ? 3.4 : 1.15
    this.fill = lerp(this.fill, this.targetFill, Math.min(1, dt * speed))
    if (Math.abs(this.fill - this.targetFill) < 0.0003) this.fill = this.targetFill
    this.full = this.fill >= 0.995

    const h = this.fill * JAR_MAX_HONEY
    const nowFull = this.fill > 0.005
    this.honey.visible = nowFull
    this.surface.visible = nowFull
    this.honey.scale.y = Math.max(0.001, h)
    this.honey.position.y = JAR_BASE_Y + h / 2
    this.surface.position.y = JAR_BASE_Y + h + 0.002
    this.surface.scale.setScalar(0.95 * (1 + Math.sin(time * 3.2) * 0.012))

    const filling = rate > 0 && !this.full
    for (const r of this.ripples) {
      const p = (time * (filling ? 0.55 : 0.2) + r.phase) % 1
      r.mesh.visible = nowFull
      r.mesh.position.y = JAR_BASE_Y + h + 0.01
      r.mesh.scale.setScalar(0.15 + p * 0.72)
      r.mesh.material.opacity = (1 - p) * (filling ? 0.55 : 0.16)
    }

    // Bubbles drift lazily upward in the honey.
    for (let i = 0; i < this.bubbles.length; i++) {
      const b = this.bubbles[i]
      const u = b.userData
      b.visible = this.fill > 0.1
      if (!b.visible) continue
      const p = (time * u.speed * 0.22 + u.phase) % 1
      b.position.set(u.x, JAR_BASE_Y + p * Math.max(0.05, h - 0.08), u.z)
      const s = u.scale * (0.7 + Math.sin(time * 3 + i) * 0.18)
      b.scale.setScalar(s)
    }

    this.innerGlow.material.opacity = 0.12 + this.fill * 0.18 + (this.full ? 0.08 + Math.sin(time * 5) * 0.04 : 0)
    this.innerGlow.position.y = 0.4 + this.fill * 0.9

    if (this.bounce > 0) {
      this.bounce = Math.max(0, this.bounce - dt * 3)
      const b = Math.sin(this.bounce * 12) * this.bounce * 0.035
      this.group.scale.y = (JAR_SCALES[this.zone?.id]?.[1] || 1) * (1 - b)
      this.group.scale.x = (JAR_SCALES[this.zone?.id]?.[0] || 1) * (1 + b * 0.5)
      this.group.scale.z = (JAR_SCALES[this.zone?.id]?.[2] || 1) * (1 + b * 0.5)
    } else if (this.zone) {
      const s = JAR_SCALES[this.zone.id] || JAR_SCALES.meadow
      this.group.scale.set(s[0], s[1], s[2])
    }

    this.fullSprite.visible = this.full
    this.fullSprite.material.opacity = lerp(this.fullSprite.material.opacity, this.full ? 1 : 0, Math.min(1, dt * 8))
    if (this.full) {
      this.fullSprite.position.y = 2.95 + Math.sin(time * 2.5) * 0.06
      const pulse = 1 + Math.sin(time * 4) * 0.02
      this.fullSprite.scale.set(2.6 * pulse, 0.91 * pulse, 1)
    }

    if (this.zone?.id === 'crystal') {
      for (const child of this.charmGroup.children) {
        if (child.isMesh) child.position.y = 2.48 + Math.sin(time * 1.8) * 0.06
        if (child.isSprite) child.position.y = 2.48 + Math.sin(time * 1.8) * 0.06
      }
    }
  }
}

function clamp01(v) {
  return Math.max(0, Math.min(1, v))
}

// Honey stream, splashes, celebration particles, hive smoke and full-jar sparkles.
import * as THREE from 'three'
import { TAU, glowTexture, rand } from './world-visuals.js'

export class HoneyStream {
  constructor(scene, spout) {
    this.spout = spout.clone()
    const geo = new THREE.CylinderGeometry(0.055, 0.095, 1, 8, 14, true)
    geo.translate(0, -0.5, 0)
    this.basePositions = Float32Array.from(geo.getAttribute('position').array)
    this.material = new THREE.MeshStandardMaterial({
      color: 0xf2a51b,
      roughness: 0.08,
      metalness: 0.15,
      emissive: 0xf2a51b,
      emissiveIntensity: 0.35,
      transparent: true,
      opacity: 0.9,
      side: THREE.DoubleSide,
      depthWrite: false,
    })
    this.mesh = new THREE.Mesh(geo, this.material)
    this.mesh.position.copy(this.spout)
    this.mesh.renderOrder = 3
    this.mesh.frustumCulled = false
    this.mesh.visible = false
    scene.add(this.mesh)
    this.normalsTick = 0

    // Droplets that fall alongside the main stream.
    this.dropMat = new THREE.MeshStandardMaterial({
      color: 0xffca4d,
      roughness: 0.05,
      metalness: 0.2,
      emissive: 0xffb300,
      emissiveIntensity: 0.45,
      transparent: true,
      opacity: 0.95,
    })
    this.dropGeo = new THREE.SphereGeometry(1, 7, 6)
    this.drops = []
    for (let i = 0; i < 7; i++) {
      const drop = new THREE.Mesh(this.dropGeo, this.dropMat)
      drop.scale.setScalar(rand(0.035, 0.07))
      drop.visible = false
      scene.add(drop)
      this.drops.push(drop)
    }

    this.splashMat = new THREE.MeshBasicMaterial({
      color: 0xffe08a,
      transparent: true,
      opacity: 0.55,
      depthWrite: false,
      side: THREE.DoubleSide,
    })
    this.splash = new THREE.Mesh(new THREE.TorusGeometry(1, 0.06, 6, 30), this.splashMat)
    this.splash.rotation.x = Math.PI / 2
    this.splash.visible = false
    scene.add(this.splash)

    // A little bead of honey always forming at the nozzle.
    this.bead = new THREE.Mesh(new THREE.SphereGeometry(0.075, 8, 6), this.dropMat)
    this.bead.position.copy(this.spout)
    this.bead.position.y -= 0.04
    scene.add(this.bead)

    this.glow = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: glowTexture(),
        color: 0xffc84d,
        transparent: true,
        opacity: 0.28,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      }),
    )
    this.glow.position.copy(this.spout)
    this.glow.position.y -= 0.2
    this.glow.scale.set(1.1, 2.2, 1)
    scene.add(this.glow)
  }

  setHoneyColor(colorHex) {
    this.material.color.setHex(colorHex)
    this.material.emissive.setHex(colorHex)
    this.dropMat.color.setHex(colorHex)
    this.dropMat.emissive.setHex(colorHex)
    this.splashMat.color.setHex(colorHex)
    this.glow.material.color.setHex(colorHex)
  }

  update(dt, time, active, surfaceY, full) {
    const length = this.spout.y - surfaceY
    const flowing = active && length > 0.15
    this.mesh.visible = flowing
    this.splash.visible = flowing
    this.glow.visible = flowing
    if (flowing) {
      const attr = this.mesh.geometry.getAttribute('position')
      const arr = attr.array
      const base = this.basePositions
      for (let i = 0; i < arr.length / 3; i++) {
        const bx = base[i * 3]
        const by = base[i * 3 + 1]
        const bz = base[i * 3 + 2]
        const t = Math.max(0, -by)
        const spread = 1 + t * 0.12
        arr[i * 3] = bx * spread + Math.sin(time * 7.5 - t * 10) * 0.035 * t
        arr[i * 3 + 1] = -t * length
        arr[i * 3 + 2] = bz * spread + Math.cos(time * 6.4 - t * 8) * 0.035 * t
      }
      attr.needsUpdate = true
      this.normalsTick += dt
      if (this.normalsTick > 0.08) {
        this.mesh.geometry.computeVertexNormals()
        this.normalsTick = 0
      }

      this.splash.position.set(this.spout.x, surfaceY + 0.02, this.spout.z)
      const pulse = 1 + Math.sin(time * 10) * 0.15
      this.splash.scale.setScalar(0.22 * pulse)
      this.splashMat.opacity = 0.32 + Math.sin(time * 8) * 0.16

      const n = this.drops.length
      for (let i = 0; i < n; i++) {
        const drop = this.drops[i]
        const p = (time * 0.46 + i / n) % 1
        drop.visible = true
        const x = this.spout.x + Math.sin(time * 6 - p * 12 + i) * 0.07 * p
        const z = this.spout.z + Math.cos(time * 5 - p * 10 + i) * 0.07 * p
        drop.position.set(x, this.spout.y - p * length, z)
        const s = 0.035 + (i % 3) * 0.011 + Math.sin(time * 8 + i) * 0.006
        drop.scale.set(s, s * 1.5, s)
      }
    } else {
      for (const drop of this.drops) drop.visible = false
    }

    // The bead swells and resets on a lazy loop.
    const beadPhase = (time * 0.55) % 1
    const growing = full ? beadPhase : 0.35
    this.bead.visible = true
    this.bead.scale.setScalar(0.75 + growing * 0.9)
    this.bead.position.y = this.spout.y - 0.03 - growing * 0.04
  }
}

export class BurstSystem {
  constructor(scene) {
    this.scene = scene
    this.parts = []
    this.rings = []
    this.geo = new THREE.IcosahedronGeometry(0.075, 0)
    this.ringGeo = new THREE.TorusGeometry(1, 0.035, 6, 32)
    this.coinGeo = new THREE.CylinderGeometry(0.11, 0.11, 0.025, 12)
    this.coinMat = new THREE.MeshStandardMaterial({
      color: 0xffd35e,
      roughness: 0.22,
      metalness: 0.8,
      emissive: 0xb87a00,
      emissiveIntensity: 0.3,
    })
  }

  spawn(position, color = 0xffc21a, count = 22, opts = {}) {
    const power = opts.power ?? 1
    for (let i = 0; i < count; i++) {
      const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 })
      const mesh = new THREE.Mesh(this.geo, mat)
      mesh.position.copy(position)
      mesh.position.x += rand(-0.35, 0.35)
      mesh.position.y += rand(-0.1, 0.55)
      mesh.position.z += rand(-0.3, 0.3)
      const s = rand(0.4, 1.35)
      mesh.scale.setScalar(s)
      this.scene.add(mesh)
      const angle = rand(0, TAU)
      const speed = rand(1.1, 3.4) * power
      this.parts.push({
        mesh,
        vel: new THREE.Vector3(
          Math.cos(angle) * speed * rand(0.3, 1),
          rand(1.6, 4.2) * power,
          Math.sin(angle) * speed * rand(0.3, 1),
        ),
        spin: new THREE.Vector3(rand(-5, 5), rand(-5, 5), rand(-5, 5)),
        life: rand(0.7, 1.4),
        maxLife: 1.4,
        baseScale: s,
      })
    }
    if (opts.coins) {
      for (let i = 0; i < opts.coins; i++) {
        const mesh = new THREE.Mesh(this.coinGeo, this.coinMat)
        mesh.position.copy(position)
        mesh.rotation.set(rand(0, 3), rand(0, 3), rand(0, 3))
        this.scene.add(mesh)
        const angle = rand(0, TAU)
        this.parts.push({
          mesh,
          vel: new THREE.Vector3(Math.cos(angle) * rand(0.6, 1.8), rand(2.2, 3.6), Math.sin(angle) * rand(0.6, 1.8)),
          spin: new THREE.Vector3(rand(-9, 9), rand(-9, 9), rand(-9, 9)),
          life: rand(1.0, 1.6),
          maxLife: 1.6,
          baseScale: 1,
          coin: true,
        })
      }
    }
    this.ring(position, color)
  }

  ring(position, color) {
    const mat = new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity: 0.75,
      side: THREE.DoubleSide,
      depthWrite: false,
    })
    const mesh = new THREE.Mesh(this.ringGeo, mat)
    mesh.position.copy(position)
    mesh.rotation.x = Math.PI / 2
    mesh.scale.setScalar(0.25)
    this.scene.add(mesh)
    this.rings.push({ mesh, life: 0, maxLife: 0.7 })
  }

  update(dt) {
    for (let i = this.parts.length - 1; i >= 0; i--) {
      const p = this.parts[i]
      p.life -= dt
      p.vel.y -= 7.2 * dt
      p.mesh.position.addScaledVector(p.vel, dt)
      p.mesh.rotation.x += p.spin.x * dt
      p.mesh.rotation.y += p.spin.y * dt
      p.mesh.rotation.z += p.spin.z * dt
      if (p.life <= 0) {
        p.mesh.removeFromParent()
        p.mesh.material?.dispose?.()
        this.parts.splice(i, 1)
        continue
      }
      if (!p.coin) {
        const k = Math.max(0, p.life / Math.max(0.2, p.maxLife))
        p.mesh.material.opacity = k
        p.mesh.scale.setScalar(p.baseScale * (0.5 + k * 0.7))
      }
    }
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i]
      r.life += dt
      const k = r.life / r.maxLife
      r.mesh.scale.setScalar(0.25 + k * 2.6)
      r.mesh.material.opacity = (1 - k) * 0.7
      if (k >= 1) {
        r.mesh.removeFromParent()
        r.mesh.material.dispose()
        this.rings.splice(i, 1)
      }
    }
  }
}

export class SmokePuffs {
  constructor(scene, origin, count = 5) {
    this.origin = origin
    this.puffs = []
    const geo = new THREE.SphereGeometry(1, 8, 6)
    for (let i = 0; i < count; i++) {
      const mat = new THREE.MeshBasicMaterial({
        color: 0xfff4df,
        transparent: true,
        opacity: 0.1,
        depthWrite: false,
      })
      const mesh = new THREE.Mesh(geo, mat)
      scene.add(mesh)
      this.puffs.push({ mesh, phase: Math.random(), speed: 0.06 + Math.random() * 0.05 })
    }
  }

  update(dt, time) {
    for (const p of this.puffs) {
      p.phase += p.speed * dt
      if (p.phase > 1) p.phase -= 1
      const t = p.phase
      p.mesh.position.set(
        this.origin.x + Math.sin(time * 0.8 + p.phase * 9) * 0.18 + t * 0.35,
        this.origin.y + t * 1.5,
        this.origin.z + Math.cos(time * 0.7 + p.phase * 7) * 0.12,
      )
      const s = 0.25 + t * 0.55
      p.mesh.scale.setScalar(s)
      p.mesh.material.opacity = Math.sin(Math.min(1, t * 1.2) * Math.PI) * 0.12
    }
  }
}

export class FullSparkles {
  constructor(parent) {
    const count = 44
    const positions = new Float32Array(count * 3)
    for (let i = 0; i < count; i++) {
      const a = rand(0, TAU)
      const r = rand(0.4, 1.5)
      positions[i * 3] = Math.cos(a) * r
      positions[i * 3 + 1] = rand(0.2, 2.4)
      positions[i * 3 + 2] = Math.sin(a) * r
    }
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3))
    const mat = new THREE.PointsMaterial({
      color: 0xffe58a,
      size: 0.075,
      transparent: true,
      opacity: 0,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      sizeAttenuation: true,
    })
    this.points = new THREE.Points(geo, mat)
    this.points.visible = false
    this.points.frustumCulled = false
    parent.add(this.points)
  }

  update(dt, time, full) {
    this.points.visible = full
    if (!full) return
    this.points.rotation.y += dt * 0.35
    this.points.material.opacity = 0.55 + Math.sin(time * 3.3) * 0.25
  }
}

// The 3D honey island: camera, hive, pipeline, jar, bees and themed scenery.
import * as THREE from 'three'
import { OrbitControls } from 'three/addons/controls/OrbitControls.js'
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js'
import { BEE_TYPES, ZONE_BY_ID } from './data.js'
import { Bee, buildBeeSpecs } from './world-bees.js'
import { createZoneEnvironment } from './world-env.js'
import { JarVisual, JAR_POS } from './jar.js'
import { makeHiveSignTexture, makeSignTexture, glowTexture, zoneVisual, clamp, rand } from './world-visuals.js'
import { BurstSystem, FullSparkles, HoneyStream, SmokePuffs } from './world-fx.js'

const ISLAND_RADIUS = 5.45

export class HoneyWorld {
  constructor(canvas, opts = {}) {
    this.canvas = canvas
    this.onJarTap = opts.onJarTap || (() => {})
    this.isCoarse = window.matchMedia('(pointer: coarse)').matches
    this.entry = new THREE.Vector3(-2.45, 0, 0.05)
    this.hiveEntry = new THREE.Vector3(-2.2, 0.85, 1.2)
    this.jarTop = new THREE.Vector3(JAR_POS.x, 2.7, JAR_POS.z)
    this.spout = new THREE.Vector3(JAR_POS.x, 3.72, JAR_POS.z)
    this.flowerPoints = []
    this.zoneGroups = new Map()
    this.zoneEnv = null
    this.zone = null
    this.visual = zoneVisual('meadow')
    this.bees = []
    this.beeSignature = ''
    this.bursts = null
    this.time = 0
    this.tapStart = null
    this.pointers = new Set()

    this.initRenderer()
    this.initScene()
    this.initLights()
    this.initSky()
    this.buildIsland()
    this.buildHive()
    this.buildPipe()
    this.buildSigns()
    this.buildJar()
    this.buildDecor()
    this.initControls()
    this.initPointer()
    this.resize()
  }

  initRenderer() {
    this.renderer = new THREE.WebGLRenderer({
      canvas: this.canvas,
      antialias: true,
      alpha: false,
      powerPreference: 'high-performance',
      preserveDrawingBuffer: true,
    })
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, this.isCoarse ? 1.85 : 2))
    this.renderer.outputColorSpace = THREE.SRGBColorSpace
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping
    this.renderer.toneMappingExposure = 1.02
    this.renderer.shadowMap.enabled = true
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap
    this.renderer.setClearColor(0xcfeaff, 1)
    this.maxAnisotropy = this.renderer.capabilities.getMaxAnisotropy()
  }

  initScene() {
    this.scene = new THREE.Scene()
    this.scene.fog = new THREE.Fog(0xcfeaff, 26, 62)
    this.camera = new THREE.PerspectiveCamera(42, 1, 0.1, 120)

    try {
      const pmrem = new THREE.PMREMGenerator(this.renderer)
      const envScene = new RoomEnvironment()
      this.scene.environment = pmrem.fromScene(envScene, 0.04).texture
      this.scene.environmentIntensity = 0.52
      envScene.traverse((o) => {
        if (o.isMesh) {
          o.geometry?.dispose?.()
          o.material?.dispose?.()
        }
      })
      pmrem.dispose()
    } catch {
      // Environment reflections are optional.
    }
  }

  initLights() {
    this.hemi = new THREE.HemisphereLight(0xfff1cf, 0x648f4b, 1.3)
    this.scene.add(this.hemi)

    this.sun = new THREE.DirectionalLight(0xffe3a3, 2.3)
    this.sun.position.set(6.5, 11, 7.5)
    this.sun.castShadow = true
    this.sun.shadow.mapSize.set(this.isCoarse ? 1024 : 2048, this.isCoarse ? 1024 : 2048)
    this.sun.shadow.camera.near = 1
    this.sun.shadow.camera.far = 34
    this.sun.shadow.camera.left = -8.5
    this.sun.shadow.camera.right = 8.5
    this.sun.shadow.camera.top = 9
    this.sun.shadow.camera.bottom = -6
    this.sun.shadow.bias = -0.0006
    this.sun.shadow.normalBias = 0.03
    this.scene.add(this.sun)

    this.fill = new THREE.DirectionalLight(0xbfe1ff, 0.55)
    this.fill.position.set(-7, 5, -6)
    this.scene.add(this.fill)

    this.jarLight = new THREE.PointLight(0xffb52e, 2.2, 7, 2)
