  buildSigns() {
    const wood = new THREE.MeshStandardMaterial({ color: 0x8e5d32, roughness: 0.82 })
    this.hiveSignMat = new THREE.MeshStandardMaterial({ map: makeHiveSignTexture(), roughness: 0.78, transparent: true })
    this.zoneSignMat = new THREE.MeshStandardMaterial({ map: makeSignTexture(ZONE_BY_ID.meadow), roughness: 0.8 })

    const makeSign = (textureMat, x, z, rot, scale = 1) => {
      const group = new THREE.Group()
      group.position.set(x, 0, z)
      group.rotation.y = rot
      const board = new THREE.Mesh(new THREE.BoxGeometry(1.5 * scale, 0.68 * scale, 0.07), wood)
      board.position.y = 1.0 * scale
      board.castShadow = true
      group.add(board)
      const face = new THREE.Mesh(new THREE.PlaneGeometry(1.46 * scale, 0.64 * scale), textureMat)
      face.position.set(0, 1.0 * scale, 0.045)
      group.add(face)
      for (const side of [-1, 1]) {
        const post = new THREE.Mesh(new THREE.CylinderGeometry(0.05 * scale, 0.06 * scale, 0.9 * scale, 6), wood)
        post.position.set(side * 0.58 * scale, 0.45 * scale, 0)
        post.castShadow = true
        group.add(post)
      }
      this.scene.add(group)
      return group
    }

    this.hiveSign = makeSign(this.hiveSignMat, -4.05, 2.55, 0.72, 1.0)
    this.zoneSign = makeSign(this.zoneSignMat, 3.62, 1.92, 0.5, 0.92)
  }

