  } else {
    const stem = mesh(G.cyl, stemMat, 0, 0.32, 0, 0.028, 0.64, 0.028)
    group.add(stem)
    const leaf = mesh(G.sphere, leafMat, 0.1, 0.3, 0.02, 0.14, 0.05, 0.08)
    leaf.rotation.z = 0.45
    group.add(leaf)
    const leaf2 = leaf.clone()
    leaf2.position.x = -0.1
